const pathByWord = new Map(Object.entries(pathWords).flatMap(([path, words]) => words.map(word => [word, path])));

export const WORDS = Object.entries(rows).flatMap(([level, entries]) => entries.map(([word, part, definition, sentence]) => ({
  word,
  part,
  definition,
  sentence,
  level,
  path: pathByWord.get(word)
})));
